import numpy as np
def clusters(g,val):
    seen=set(); out=[]
    for i in range(len(g)):
        for j in range(len(g[0])):
            if g[i][j]==val and (i,j) not in seen:
                st=[(i,j)];seen.add((i,j));cells=[]
                while st:
                    a,b=st.pop();cells.append((a,b))
                    for da in(-1,0,1):
                        for db in(-1,0,1):
                            x,y=a+da,b+db
                            if 0<=x<len(g) and 0<=y<len(g[0]) and g[x][y]==val and (x,y) not in seen:
                                seen.add((x,y));st.append((x,y))
                out.append(cells)
    return out
